mapper.select:
SELECT i.amount_minor
FROM prc_price_item i
JOIN prc_price_book b ON b.tenant_id = i.tenant_id AND b.price_book_id = i.price_book_id
WHERE i.tenant_id = #{tenantId}
  AND i.sku_id = #{skuId} AND i.unit_id = #{unitId}
  AND b.state = 'PUBLISHED'
  AND b.price_book_id <> #{excludedPriceBookId}
  AND (b.scope_type = 'TENANT_BASE' OR (b.scope_type = 'STORE' AND b.store_id = #{storeId}))
  AND i.effective_from <= #{effectiveAt}
  AND (i.effective_to IS NULL OR i.effective_to > #{effectiveAt})
ORDER BY (b.scope_type = 'STORE') DESC, b.version_no DESC, b.price_book_id DESC, i.price_item_id DESC
LIMIT 1
